/* Workspace row sits 12px above the input card (figma y80 → y112). The blue
   glow lives with the owner (ConversationRoot .heroGlow) so it can center on
   the input card. */
.body {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  overflow: visible;
}

.body > * {
